inputs = ['ub', 'ckyg', 'huchc', 'ebhiwj', 'hz']
outputs = ['ucau', 'ckyg', 'huchc', 'ecauhiwj', 'haaz']

# Let's manually trace through what transformations would be needed
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Input: '{inp}' -> Output: '{outp}'")

    # Find differences
    min_len = min(len(inp), len(outp))
    diff_positions = []
    for j in range(min_len):
        if inp[j] != outp[j]:
            diff_positions.append((j, inp[j], outp[j]))

    # Check if there's a pattern with length differences
    if len(inp) != len(outp):
        if len(inp) > len(outp):
            print(f"  Length decreased from {len(inp)} to {len(outp)}")
        else:
            print(f"  Length increased from {len(inp)} to {len(outp)}")

    if diff_positions:
        print(f"  Differences at positions: {diff_positions}")
    else:
        print("  No character differences")
    print()

